-- Authoritative replay/parity, receipts, validation, category isolation and memory lifecycle.
begin;
create extension if not exists pgtap with schema extensions;
select plan(130);

do $$begin perform set_config('roam.test.m4_token', replace(gen_random_uuid()::text, '-', ''), true); end$$;
insert into auth.users(id, instance_id, aud, role, email, encrypted_password, email_confirmed_at, raw_app_meta_data, raw_user_meta_data, created_at, updated_at)
select id, '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', email, '', now(),
       '{"provider":"email","providers":["email"]}', '{}', now(), now()
from (values ('a4000000-0000-4000-8000-000000000001'::uuid, 'm4-owner@test.local'),
             ('b4000000-0000-4000-8000-000000000002'::uuid, 'm4-other@test.local'),
             ('c4000000-0000-4000-8000-000000000003'::uuid, 'm4-golden@test.local')) u(id,email);
insert into public.profiles(id,handle,display_name) values
  ('a4000000-0000-4000-8000-000000000001','m4_owner','M4 Owner'),
  ('b4000000-0000-4000-8000-000000000002','m4_other','M4 Other'),
  ('c4000000-0000-4000-8000-000000000003','m4_golden','M4 Golden');

create temporary table m4_cases(label text primary key, experience uuid not null, request jsonb, response jsonb) on commit drop;
grant select,insert,update on m4_cases to authenticated;
create function pg_temp.m4_request(p_experience uuid, p_category text, p_sentiment text, p_revision bigint,
                                  p_answers jsonb default '[]', p_intent text default 'first_log',
                                  p_visit jsonb default null, p_operation uuid default gen_random_uuid())
returns jsonb language sql as $$
  select jsonb_build_object('operationID', p_operation, 'intent', p_intent, 'experienceID', p_experience, 'category', p_category,
                           'sentiment', p_sentiment, 'baseRevision', p_revision, 'answers', p_answers, 'visit', p_visit)
$$;
create function pg_temp.m4_answer(p_rating uuid, p_choice text)
returns jsonb language sql as $$select jsonb_build_array(jsonb_build_object('compared_rating_id',p_rating,'choice',p_choice))$$;
create function pg_temp.m4_log(p_label text, p_category text, p_sentiment text, p_answers jsonb default '[]', p_visit jsonb default null)
returns void language plpgsql as $$
declare experience uuid; request jsonb; response jsonb;
begin
  experience := (public.resolve_place(jsonb_build_object('provider','mapkit','providerPlaceID','I-M4-'||current_setting('roam.test.m4_token')||p_label,
      'name','M4 '||p_label,'latitude',10.1,'longitude',20.2,'isLocality',false,'suggestedCategory',p_category)) ->> 'id')::uuid;
  request := pg_temp.m4_request(experience,p_category,p_sentiment,(public.category_ranking(p_category::public.experience_category)->>'revision')::bigint,p_answers,'first_log',p_visit);
  response := public.commit_rating(request);
  insert into m4_cases values(p_label,experience,request,response);
end;
$$;
grant execute on function pg_temp.m4_request(uuid,text,text,bigint,jsonb,text,jsonb,uuid), pg_temp.m4_answer(uuid,text), pg_temp.m4_log(text,text,text,jsonb,jsonb) to authenticated;

create function pg_temp.m4_force_activity_failure()
returns trigger language plpgsql as $$begin
  if current_setting('roam.test.m4_fail_activity',true)='yes' and new.author_id='a4000000-0000-4000-8000-000000000001' then
    raise exception 'm4:injected_activity_failure';
  end if;
  return new;
end$$;
create trigger m4_forced_activity_failure before insert on public.activities for each row execute function pg_temp.m4_force_activity_failure();

create temporary table m4_assets(label text primary key,id uuid,owner uuid,path text) on commit drop;
insert into m4_assets values
  ('first','d4000000-0000-4000-8000-000000000001','a4000000-0000-4000-8000-000000000001','a4000000-0000-4000-8000-000000000001/m4-'||current_setting('roam.test.m4_token')||'-first.jpg'),
  ('second','d4000000-0000-4000-8000-000000000002','a4000000-0000-4000-8000-000000000001','a4000000-0000-4000-8000-000000000001/m4-'||current_setting('roam.test.m4_token')||'-second.jpg'),
  ('foreign','d4000000-0000-4000-8000-000000000003','b4000000-0000-4000-8000-000000000002','b4000000-0000-4000-8000-000000000002/m4-'||current_setting('roam.test.m4_token')||'-foreign.jpg'),
  ('missing','d4000000-0000-4000-8000-000000000004','a4000000-0000-4000-8000-000000000001','a4000000-0000-4000-8000-000000000001/m4-'||current_setting('roam.test.m4_token')||'-missing.jpg');
grant select on m4_assets to authenticated;
insert into storage.objects(bucket_id,name,owner,metadata) select 'visit-media',path,owner,'{"size":128,"mimetype":"image/jpeg"}' from m4_assets where label<>'missing';
insert into public.media(id,owner_id,purpose,bucket,object_path,byte_size,width,height)
select id,owner,'visit','visit-media',path,128,64,64 from m4_assets;

-- Shared docs/data/m4-ranking-golden.json inputs are embedded below so pgTAP does not depend
-- on a host filesystem path. Swift's engine tests consume that same checked-in source.
create temporary table m4_goldens(kind text, input jsonb) on commit drop;
create function pg_temp.m4_representatives(p_case jsonb)
returns uuid[] language plpgsql as $$
declare groups jsonb; grp jsonb; representative uuid; result uuid[] := '{}';
begin
  groups := case when jsonb_typeof(p_case->'groups')='array' then p_case->'groups' else p_case->'groups'->(p_case->>'sentiment') end;
  for grp in select value from jsonb_array_elements(groups) loop
    select (e->>'ratingID')::uuid into representative from jsonb_array_elements(grp) e
      where p_case->>'removingExperienceID' is null or e->>'experienceID' <> p_case->>'removingExperienceID'
      order by (e->>'firstRatedAtSeconds')::numeric, (e->>'ratingID')::uuid limit 1;
    if representative is not null then result := array_append(result,representative); end if;
  end loop;
  return result;
end;
$$;
create function pg_temp.m4_golden_scores(p_case jsonb)
returns jsonb language plpgsql as $$
declare partition record; grp record; entry jsonb; result jsonb;
begin
  delete from public.ratings where owner_id='c4000000-0000-4000-8000-000000000003';
  for partition in select key,value from jsonb_each(p_case->'groups') loop
    for grp in select value,ordinality from jsonb_array_elements(partition.value) with ordinality loop
      for entry in select value from jsonb_array_elements(grp.value) loop
        insert into public.places(id,provider,provider_place_id,name,normalized_name,latitude,longitude)
        values((entry->>'experienceID')::uuid,'fixture',entry->>'experienceID',entry->>'name',entry->>'name',1,1) on conflict(id) do nothing;
        insert into public.experiences(id,place_id,category)
        values((entry->>'experienceID')::uuid,(entry->>'experienceID')::uuid,(p_case->>'category')::public.experience_category)
        on conflict(id) do update set category=excluded.category;
        insert into public.ratings(id,owner_id,experience_id,category,sentiment,group_position,score,rank,first_rated_at)
        values((entry->>'ratingID')::uuid,'c4000000-0000-4000-8000-000000000003',(entry->>'experienceID')::uuid,
          (p_case->>'category')::public.experience_category,partition.key::public.sentiment,grp.ordinality-1,0,1,to_timestamp((entry->>'firstRatedAtSeconds')::double precision));
      end loop;
    end loop;
  end loop;
  perform app_private.reflow_rating_category('c4000000-0000-4000-8000-000000000003',(p_case->>'category')::public.experience_category);
  select jsonb_agg(jsonb_build_object('ratingID',r.id,'sentiment',r.sentiment,'scoreTenths',(r.score*10)::integer,'rank',r.rank,
    'groupSize',(select count(*) from public.ratings g where g.owner_id=r.owner_id and g.category=r.category and g.sentiment=r.sentiment and g.group_position=r.group_position))
    order by r.sentiment,r.group_position,r.first_rated_at,r.id) into result
  from public.ratings r where r.owner_id='c4000000-0000-4000-8000-000000000003';
  return coalesce(result,'[]');
end;
$$;

