select is(pg_temp.m4_golden_scores(input),input->'expectedPlacements','shared scoring golden: '||(input->>'name')) from m4_goldens where kind='scoringCases';
select is(app_private.replay_insertion(pg_temp.m4_representatives(input),input->'answers'),input->'expectedOutcome','shared insertion golden: '||(input->>'name'))
from m4_goldens where kind='insertionCases';
select throws_ok(format('select app_private.replay_insertion(%L::uuid[],%L::jsonb)',pg_temp.m4_representatives(input),input->'answers'),'22023',null,
                 'shared rejected replay: '||(input->>'name')) from m4_goldens where kind='rejectionCases';

set local role authenticated;
set local request.jwt.claims to '{"sub":"a4000000-0000-4000-8000-000000000001","role":"authenticated"}';
select throws_ok($$select app_private.replay_insertion('{}'::uuid[],'[]')$$,'42501',null,'clients cannot call the trusted replay helper');
select is(public.category_ranking('food_drink')->'liked','[]'::jsonb,'new member starts with empty ranking');
do $$declare category public.experience_category; begin
  foreach category in array enum_range(null::public.experience_category) loop perform pg_temp.m4_log('first-'||category,category::text,'liked'); end loop;
end$$;
select is((select count(*)::int from public.ratings where owner_id='a4000000-0000-4000-8000-000000000001'),7,'all seven independent categories accept the first rating');
select is((select count(*)::int from public.visits where owner_id='a4000000-0000-4000-8000-000000000001'),7,'first rankings create exactly one Visit each');
select is((select count(*)::int from public.activities where author_id='a4000000-0000-4000-8000-000000000001'),7,'first rankings automatically create one activity each');
select is((select count(*)::int from public.ratings where owner_id='a4000000-0000-4000-8000-000000000001' and score=8.4 and rank=1),7,'first liked score is8.4 from every category');
select is(public.commit_rating((select request from m4_cases where label='first-food_drink')),(select response from m4_cases where label='first-food_drink'),'duplicate first-log returns the exact original receipt before revision/state checks');
select throws_ok(format('select public.commit_rating(%L::jsonb)',(select request||jsonb_build_object('sentiment','fine') from m4_cases where label='first-food_drink')),'23505','roam:operation_conflict','a changed payload under an acknowledged UUID is rejected');
select throws_ok(format('select public.commit_rating(%L::jsonb)',(select request||jsonb_build_object('actorID','b4000000-0000-4000-8000-000000000002') from m4_cases where label='first-food_drink')),'22023',null,'actor spoofing is rejected at the request boundary');
select throws_ok(format('select public.commit_rating(%L::jsonb)',(select request||jsonb_build_object('score',10) from m4_cases where label='first-food_drink')),'22023',null,'client-provided scores are rejected');
select throws_ok(format('select public.commit_rating(%L::jsonb)',(select request||jsonb_build_object('order',jsonb_build_array('forged')) from m4_cases where label='first-food_drink')),'22023',null,'client-provided ranking order is rejected');
do $$begin
  perform pg_temp.m4_log('food-2','food_drink','liked',pg_temp.m4_answer((select (response->>'ratingID')::uuid from m4_cases where label='first-food_drink'),'prefer_existing'));
end$$;
select is((select score from public.ratings where id=(select (response->>'ratingID')::uuid from m4_cases where label='first-food_drink')),10.0::numeric,'second liked group reflows first score to10.0');
select is((select (response->>'score')::numeric from m4_cases where label='food-2'),6.7::numeric,'second liked group gets6.7');
select is((select score_snapshot from public.activities where id=(select (response->>'activityID')::uuid from m4_cases where label='first-food_drink')),8.4::numeric,'historical activity score remains8.4 after current reflow');
do $$begin
  perform pg_temp.m4_log('food-3','food_drink','liked',pg_temp.m4_answer((select (response->>'ratingID')::uuid from m4_cases where label='food-2'),'prefer_existing'));
  perform pg_temp.m4_log('food-fine','food_drink','fine');
  perform pg_temp.m4_log('food-disliked','food_drink','disliked');
end$$;
select is((select jsonb_agg(score order by group_position) from public.ratings where owner_id='a4000000-0000-4000-8000-000000000001' and category='food_drink' and sentiment='liked'), '[10.0,8.4,6.7]'::jsonb,'three distinct liked groups use10.0/8.4/6.7');
select is((select (response->>'score')::numeric from m4_cases where label='food-fine'),5.0::numeric,'first fine group scores5.0');
select is((select (response->>'score')::numeric from m4_cases where label='food-disliked'),1.7::numeric,'first disliked group scores1.7');
select is((select score from public.ratings where id=(select (response->>'ratingID')::uuid from m4_cases where label='first-outdoors')),8.4::numeric,'Food reflow never changes Outdoors');
select is((public.category_ranking('outdoors')->>'revision')::int,1,'Food mutations never increment Outdoors revision');

-- An invalid first-log may not consume its UUID, remove Want, or leave partial rows/revision.
insert into m4_cases(label,experience) select 'failure',(public.resolve_place(jsonb_build_object('provider','mapkit','providerPlaceID','I-M4-FAIL-'||current_setting('roam.test.m4_token'),'name','Rollback Place','latitude',11,'longitude',22,'isLocality',false))->>'id')::uuid;
update m4_cases set request=pg_temp.m4_request(experience,'food_drink','liked',(public.category_ranking('food_drink')->>'revision')::bigint) where label='failure';
select is(public.set_bookmark((select experience from m4_cases where label='failure'),true),true,'failure target starts saved in Want');
select throws_ok(format('select public.commit_rating(%L::jsonb)',(select request from m4_cases where label='failure')),'22023',null,'incomplete comparison chain is rejected');
select throws_ok(format('select public.commit_rating(%L::jsonb)',(select request||jsonb_build_object('answers',pg_temp.m4_answer(gen_random_uuid(),'too_tough')) from m4_cases where label='failure')),'22023',null,'wrong comparison representative is rejected');
select throws_ok(format('select public.commit_rating(%L::jsonb)',(select request||jsonb_build_object('baseRevision',0) from m4_cases where label='failure')),'40001','roam:stale_revision','stale category revision is rejected');
select throws_ok(format('select public.commit_rating(%L::jsonb)',(select request||jsonb_build_object('answers',pg_temp.m4_answer((select (response->>'ratingID')::uuid from m4_cases where label='food-2'),'skip'),'visit',jsonb_build_object('date','9999-12-31','publicNote','','mediaIDs','[]'::jsonb)) from m4_cases where label='failure')),'22023',null,'future visit fails before durable mutation');
select is((select count(*)::int from public.ratings where experience_id=(select experience from m4_cases where label='failure')),0,'failed save leaves no Rating');
select is((select count(*)::int from public.visits where experience_id=(select experience from m4_cases where label='failure')),0,'failed save leaves no Visit');
select is((select count(*)::int from public.activities where experience_id=(select experience from m4_cases where label='failure')),0,'failed save leaves no activity');
select is((public.category_ranking('food_drink')->>'revision')::int,(select (request->>'baseRevision')::int from m4_cases where label='failure'),'failed saves leave category revision unchanged');
select is(public.set_bookmark((select experience from m4_cases where label='failure'),true),true,'failed saves leave Want untouched');
select throws_ok(format('select public.commit_rating(%L::jsonb)',(select request||jsonb_build_object('answers',pg_temp.m4_answer((select (response->>'ratingID')::uuid from m4_cases where label='food-2'),'skip'),'visit',jsonb_build_object('mediaIDs',jsonb_build_array((select id from m4_assets where label='foreign')))) from m4_cases where label='failure')),'22023',null,'another member staged upload cannot attach to the Visit');
select throws_ok(format('select public.commit_rating(%L::jsonb)',(select request||jsonb_build_object('answers',pg_temp.m4_answer((select (response->>'ratingID')::uuid from m4_cases where label='food-2'),'skip'),'visit',jsonb_build_object('mediaIDs',jsonb_build_array((select id from m4_assets where label='missing')))) from m4_cases where label='failure')),'22023',null,'registered media with no completed Storage object cannot attach');
select throws_ok(format('select public.commit_rating(%L::jsonb)',(select request||jsonb_build_object('answers',pg_temp.m4_answer((select (response->>'ratingID')::uuid from m4_cases where label='food-2'),'skip'),'visit',jsonb_build_object('mediaIDs',jsonb_build_array((select id from m4_assets where label='first'),(select id from m4_assets where label='first')))) from m4_cases where label='failure')),'22023',null,'duplicate photo references are rejected');
update m4_cases set request=request||jsonb_build_object('answers',pg_temp.m4_answer((select (response->>'ratingID')::uuid from m4_cases where label='food-2'),'skip')) where label='failure';
update m4_cases set response=public.commit_rating(request) where label='failure';
select is((select (response->>'rank')::int from m4_cases where label='failure'),2,'Skip inserts a separate group at the remaining midpoint');
select is((select count(*)::int from public.bookmarks where owner_id='a4000000-0000-4000-8000-000000000001' and experience_id=(select experience from m4_cases where label='failure')),0,'successful first-log atomically removes Want');
select throws_ok(format('select public.set_bookmark(%L,true)',(select experience from m4_cases where label='failure')),'22023','roam:already_rated','a rated experience cannot be saved again');

-- Force a failure after Rating/revision/Visit/Want writes, rather than relying on prevalidation.
insert into m4_cases(label,experience) select 'atomic',(public.resolve_place(jsonb_build_object('provider','mapkit','providerPlaceID','I-M4-ATOMIC-'||current_setting('roam.test.m4_token'),'name','Atomic Rollback Place','latitude',11,'longitude',22,'isLocality',false))->>'id')::uuid;
update m4_cases set request=pg_temp.m4_request(experience,'nightlife','fine',(public.category_ranking('nightlife')->>'revision')::bigint) where label='atomic';
do $$begin
  perform public.set_bookmark((select experience from m4_cases where label='atomic'),true);
  perform set_config('roam.test.m4_fail_activity','yes',true);
end$$;
select throws_ok(format('select public.commit_rating(%L::jsonb)',(select request from m4_cases where label='atomic')),'P0001','m4:injected_activity_failure','activity insertion failure rolls back the entire first-log');
do $$begin perform set_config('roam.test.m4_fail_activity','no',true); end$$;
select is((select count(*)::int from public.ratings where experience_id=(select experience from m4_cases where label='atomic')),0,'post-write failure rolls back Rating');
select is((select count(*)::int from public.visits where experience_id=(select experience from m4_cases where label='atomic')),0,'post-write failure rolls back Visit');
select is((select count(*)::int from public.activities where experience_id=(select experience from m4_cases where label='atomic')),0,'post-write failure leaves no activity');
select is((select count(*)::int from public.bookmarks where owner_id='a4000000-0000-4000-8000-000000000001' and experience_id=(select experience from m4_cases where label='atomic')),1,'post-write failure restores Want');
select is((public.category_ranking('nightlife')->>'revision')::int,(select (request->>'baseRevision')::int from m4_cases where label='atomic'),'post-write failure restores category revision');
update m4_cases set response=public.commit_rating(request) where label='atomic';
select is((select (response->>'revision')::int from m4_cases where label='atomic'),2,'same operation succeeds after acknowledged transaction rollback');

-- Rerank removes the old item from comparisons, keeps identity and updates its retained memory.
insert into m4_cases(label,experience,request) select 'rerank',experience,
  pg_temp.m4_request(experience,'food_drink','fine',(public.category_ranking('food_drink')->>'revision')::bigint,
    pg_temp.m4_answer((select (response->>'ratingID')::uuid from m4_cases where label='food-fine'),'too_tough'),'rerank',
    jsonb_build_object('date','2020-01-02','timeZoneIdentifier','America/Toronto','publicNote',repeat('n',5000),'mediaIDs','[]'::jsonb))
from m4_cases where label='first-food_drink';
update m4_cases set response=public.commit_rating(request) where label='rerank';
select is((select response->>'ratingID' from m4_cases where label='rerank'),(select response->>'ratingID' from m4_cases where label='first-food_drink'),'rerank preserves Rating UUID');
select is((select response->'visitID' from m4_cases where label='rerank'),'null'::jsonb,'rerank creates no new Visit receipt');
select is((select count(*)::int from public.visits where owner_id='a4000000-0000-4000-8000-000000000001' and experience_id=(select experience from m4_cases where label='rerank')),1,'rerank retains exactly one Visit');
select is((select visit_date::text from public.visits where id=(select (response->>'visitID')::uuid from m4_cases where label='first-food_drink')),'2020-01-02','rerank enrichment edits date on retained Visit');
select is((select char_length(public_note) from public.visits where id=(select (response->>'visitID')::uuid from m4_cases where label='first-food_drink')),5000,'public note boundary of5,000 characters persists');
select is(public.commit_rating((select request from m4_cases where label='rerank')),(select response from m4_cases where label='rerank'),'rerank retry returns the original result');
select throws_ok(format('select public.commit_rating(%L::jsonb)',(select jsonb_set(request,'{visit,publicNote}','"changed"') from m4_cases where label='rerank')),'23505','roam:operation_conflict','changed rerank enrichment under its UUID conflicts');
select throws_ok(format('select public.commit_rating(%L::jsonb)',(select request||jsonb_build_object('operationID',gen_random_uuid(),'category','outdoors') from m4_cases where label='rerank')),'22023',null,'canonical category cannot change during rerank');

insert into m4_cases(label,experience,request) select 'revisit',experience,jsonb_build_object('operationID',gen_random_uuid(),'experienceID',experience,'visit',jsonb_build_object('date',null,'publicNote','Second retained memory','mediaIDs','[]'::jsonb)) from m4_cases where label='first-food_drink';
update m4_cases set response=public.add_visit(request) where label='revisit';
select is((select count(*)::int from public.visits where owner_id='a4000000-0000-4000-8000-000000000001' and experience_id=(select experience from m4_cases where label='revisit')),2,'Add visit creates exactly one further Visit');
select is((public.category_ranking('food_drink')->>'revision')::int,(select (response->>'revision')::int from m4_cases where label='rerank'),'Add visit does not change category revision');
select is(public.add_visit((select request from m4_cases where label='revisit')),(select response from m4_cases where label='revisit'),'revisit receipt deduplicates retries');
select throws_ok(format('select public.add_visit(%L::jsonb)',(select jsonb_set(request,'{visit,publicNote}',to_jsonb(repeat('x',5001)))||jsonb_build_object('operationID',gen_random_uuid()) from m4_cases where label='revisit')),'22023',null,'5,001-character public note is rejected');
select throws_ok(format('select public.add_visit(%L::jsonb)',(select jsonb_set(request,'{visit,date}','"2026-02-30"')||jsonb_build_object('operationID',gen_random_uuid()) from m4_cases where label='revisit')),'22023',null,'invalid calendar date is rejected');
select throws_ok(format('select public.add_visit(%L::jsonb)',(select jsonb_set(request,'{visit,timeZoneIdentifier}','"Moon/Sea"')||jsonb_build_object('operationID',gen_random_uuid()) from m4_cases where label='revisit')),'22023',null,'invalid time zone is rejected');

reset role;
insert into public.private_notes(owner_id,experience_id,body) select 'a4000000-0000-4000-8000-000000000001',experience,'Private retained text' from m4_cases where label='first-food_drink';
set local role authenticated;
set local request.jwt.claims to '{"sub":"a4000000-0000-4000-8000-000000000001","role":"authenticated"}';
insert into m4_cases(label,experience,request) select 'remove',experience,jsonb_build_object('operationID',gen_random_uuid()) from m4_cases where label='first-food_drink';
update m4_cases set response=public.remove_rating(experience,(request->>'operationID')::uuid) where label='remove';
select is((select count(*)::int from public.ratings where owner_id='a4000000-0000-4000-8000-000000000001' and experience_id=(select experience from m4_cases where label='remove')),0,'Remove ranking deletes only current Rating');
select is((select count(*)::int from public.visits where owner_id='a4000000-0000-4000-8000-000000000001' and experience_id=(select experience from m4_cases where label='remove')),2,'Remove ranking retains actual populated Visits');
select is((select count(*)::int from public.private_notes where owner_id='a4000000-0000-4000-8000-000000000001'),1,'Remove ranking retains PrivateNote');
select is((select count(*)::int from public.activities where author_id='a4000000-0000-4000-8000-000000000001' and experience_id=(select experience from m4_cases where label='remove')),0,'Remove ranking cascades every rating-linked activity');
select is(public.remove_rating((select experience from m4_cases where label='remove'),(select (request->>'operationID')::uuid from m4_cases where label='remove')),'{}'::jsonb,'Remove ranking repeats its original receipt');
select is((select count(*)::int from public.bookmarks where owner_id='a4000000-0000-4000-8000-000000000001' and experience_id=(select experience from m4_cases where label='remove')),0,'Remove ranking does not restore Want');
insert into m4_cases(label,experience,request) select 'relog',experience,
  pg_temp.m4_request(experience,'food_drink','fine',(public.category_ranking('food_drink')->>'revision')::bigint,
    pg_temp.m4_answer((select (response->>'ratingID')::uuid from m4_cases where label='food-fine'),'too_tough'))
from m4_cases where label='first-food_drink';
update m4_cases set response=public.commit_rating(request) where label='relog';
do $$begin perform public.remove_rating((select experience from m4_cases where label='remove'),(select (request->>'operationID')::uuid from m4_cases where label='remove')); end$$;
select is((select id::text from public.ratings where owner_id='a4000000-0000-4000-8000-000000000001' and experience_id=(select experience from m4_cases where label='relog')),(select response->>'ratingID' from m4_cases where label='relog'),'old removal receipt cannot delete a later Rating');
select is((public.delete_visit((select (response->>'visitID')::uuid from m4_cases where label='relog'),gen_random_uuid())->>'removedRating')::boolean,false,'deleting one of several Visits retains the current Rating');

do $$begin perform pg_temp.m4_log('photos','activities','fine','[]',jsonb_build_object('date','2020-01-02','publicNote','Retained photo memory','mediaIDs',
  jsonb_build_array((select id from m4_assets where label='first'),(select id from m4_assets where label='second')))); end$$;
select is((select count(*)::int from public.media where visit_id=(select (response->>'visitID')::uuid from m4_cases where label='photos') and state='attached'),2,'fully uploaded owned media attaches atomically');
select is(public.commit_rating((select request from m4_cases where label='photos')),(select response from m4_cases where label='photos'),'media attachment state does not invalidate an existing receipt');
insert into m4_cases(label,experience,request) select 'photo-rerank',experience,
  pg_temp.m4_request(experience,'activities','fine',(public.category_ranking('activities')->>'revision')::bigint,'[]','rerank',
    jsonb_build_object('date','2021-02-03','publicNote','Updated photo memory','mediaIDs',jsonb_build_array((select id from m4_assets where label='second'),(select id from m4_assets where label='first'))))
from m4_cases where label='photos';
update m4_cases set response=public.commit_rating(request) where label='photo-rerank';
select is((select jsonb_agg(id::text order by position) from public.media where visit_id=(select (response->>'visitID')::uuid from m4_cases where label='photos')),
          jsonb_build_array((select id from m4_assets where label='second'),(select id from m4_assets where label='first')),'rerank can reorder existing assets on its retained Visit');
select is((select count(*)::int from public.visits where owner_id='a4000000-0000-4000-8000-000000000001' and experience_id=(select experience from m4_cases where label='photos')),1,'photo-enriched rerank creates no extra Visit');
insert into m4_cases(label,experience,request) select 'photo-removal',experience,
  pg_temp.m4_request(experience,'activities','fine',(public.category_ranking('activities')->>'revision')::bigint,'[]','rerank',
    jsonb_build_object('date','2021-02-03','publicNote','Updated photo memory','mediaIDs',jsonb_build_array((select id from m4_assets where label='second'))))
from m4_cases where label='photos';
update m4_cases set response=public.commit_rating(request) where label='photo-removal';
select is((select count(*)::int from public.media where id=(select id from m4_assets where label='first')),0,'explicit photo omission removes that media row');
do $$begin perform public.remove_rating((select experience from m4_cases where label='photos'),gen_random_uuid()); end$$;
select is((select count(*)::int from public.media where visit_id=(select (response->>'visitID')::uuid from m4_cases where label='photos') and state='attached'),1,'ranking removal retains real populated Visit media');
select is((select public_note from public.visits where id=(select (response->>'visitID')::uuid from m4_cases where label='photos')),'Updated photo memory','ranking removal retains populated public note');

-- Both dialogs were opened with two Visits. The second ordinary deletion must not silently
-- become a destructive Rating removal after the first client deletes the other Visit.
insert into m4_cases(label,experience,request) select 'consent-second',experience,
  jsonb_build_object('operationID',gen_random_uuid(),'experienceID',experience,'visit',jsonb_build_object('publicNote','Second consent memory','mediaIDs','[]'::jsonb))
from m4_cases where label='first-culture';
update m4_cases set response=public.add_visit(request) where label='consent-second';
insert into m4_cases(label,experience,request) select 'consent-first',experience,jsonb_build_object('operationID',gen_random_uuid(),'visitID',response->>'visitID') from m4_cases where label='first-culture';
insert into m4_cases(label,experience,request) select 'consent-stale',experience,jsonb_build_object('operationID',gen_random_uuid(),'visitID',response->>'visitID') from m4_cases where label='consent-second';
update m4_cases set response=public.delete_visit((request->>'visitID')::uuid,(request->>'operationID')::uuid,false) where label='consent-first';
select is((select response->'removedRating' from m4_cases where label='consent-first'),'false'::jsonb,'ordinary deletion of one of two Visits retains Rating');
select throws_ok(format('select public.delete_visit(%L,%L,false)',(select request->>'visitID' from m4_cases where label='consent-stale'),(select request->>'operationID' from m4_cases where label='consent-stale')),'22023','roam:confirm_last_visit','stale ordinary confirmation cannot remove the now-last Visit and Rating');
select is((select count(*)::int from public.visits where owner_id='a4000000-0000-4000-8000-000000000001' and experience_id=(select experience from m4_cases where label='consent-stale')),1,'consent rejection retains the last Visit');
select is((select count(*)::int from public.ratings where owner_id='a4000000-0000-4000-8000-000000000001' and experience_id=(select experience from m4_cases where label='consent-stale')),1,'consent rejection retains Rating');
select throws_ok(format('select public.delete_visit(%L,%L,true)',(select request->>'visitID' from m4_cases where label='consent-first'),(select request->>'operationID' from m4_cases where label='consent-first')),'23505','roam:operation_conflict','changing Rating-removal consent under an acknowledged UUID conflicts');
insert into m4_cases(label,experience,request) select 'consent-final',experience,request||jsonb_build_object('operationID',gen_random_uuid()) from m4_cases where label='consent-stale';
update m4_cases set response=public.delete_visit((request->>'visitID')::uuid,(request->>'operationID')::uuid,true) where label='consent-final';
select is((select response->'removedRating' from m4_cases where label='consent-final'),'true'::jsonb,'explicit last-Visit consent removes Rating');
select is(public.delete_visit((select (request->>'visitID')::uuid from m4_cases where label='consent-final'),(select (request->>'operationID')::uuid from m4_cases where label='consent-final'),true),(select response from m4_cases where label='consent-final'),'confirmed deletion repeats its original result before checking current state');
select is((select count(*)::int from public.visits where owner_id='a4000000-0000-4000-8000-000000000001' and experience_id=(select experience from m4_cases where label='consent-final')),0,'confirmed final deletion removes the last Visit');
select is((select count(*)::int from public.ratings where owner_id='a4000000-0000-4000-8000-000000000001' and experience_id=(select experience from m4_cases where label='consent-final')),0,'confirmed final deletion removes the Rating');

-- A last-Visit receipt stays true on retries; foreign writes remain blocked.
insert into m4_cases(label,experience,request) select 'delete-last',experience,jsonb_build_object('operationID',gen_random_uuid(),'visitID',response->>'visitID') from m4_cases where label='first-stays';
update m4_cases set response=public.delete_visit((request->>'visitID')::uuid,(request->>'operationID')::uuid,true) where label='delete-last';
select is((select response->'removedRating' from m4_cases where label='delete-last'),'true'::jsonb,'deleting the last Visit removes its Rating');
select is(public.delete_visit((select (request->>'visitID')::uuid from m4_cases where label='delete-last'),(select (request->>'operationID')::uuid from m4_cases where label='delete-last'),true),(select response from m4_cases where label='delete-last'),'last-Visit retry retains original removedRating=true');
select is((select count(*)::int from public.visits where experience_id=(select experience from m4_cases where label='delete-last')),0,'last-Visit deletion removes its memory');
select is((select count(*)::int from public.activities where experience_id=(select experience from m4_cases where label='delete-last')),0,'last-Visit deletion cascades its activity');
insert into m4_cases(label,experience,request) select 'stays-relog',experience,
  pg_temp.m4_request(experience,'stays','liked',(public.category_ranking('stays')->>'revision')::bigint) from m4_cases where label='first-stays';
update m4_cases set response=public.commit_rating(request) where label='stays-relog';
do $$begin perform public.delete_visit((select (request->>'visitID')::uuid from m4_cases where label='delete-last'),(select (request->>'operationID')::uuid from m4_cases where label='delete-last'),true); end$$;
select is((select count(*)::int from public.visits where owner_id='a4000000-0000-4000-8000-000000000001' and experience_id=(select experience from m4_cases where label='stays-relog')),1,'old Visit deletion receipt cannot delete a later Visit');
select is((select id::text from public.ratings where owner_id='a4000000-0000-4000-8000-000000000001' and experience_id=(select experience from m4_cases where label='stays-relog')),(select response->>'ratingID' from m4_cases where label='stays-relog'),'old Visit deletion receipt cannot remove a later Rating');
set local request.jwt.claims to '{"sub":"b4000000-0000-4000-8000-000000000002","role":"authenticated"}';
select throws_ok(format('select public.delete_visit(%L,%L)',(select response->>'visitID' from m4_cases where label='revisit'),gen_random_uuid()),'42501','roam:forbidden','another actor cannot delete an owned Visit');
select is(public.category_ranking('food_drink')->'liked','[]'::jsonb,'category ranking contains only the JWT actor');
insert into m4_cases(label,experience,request,response) select 'other-same-operation',experience,request,public.commit_rating(request) from m4_cases where label='first-food_drink';
select isnt((select response->>'ratingID' from m4_cases where label='other-same-operation'),(select response->>'ratingID' from m4_cases where label='first-food_drink'),'same UUID used by another actor produces only that actor receipt');
select is(public.experience_detail((select experience from m4_cases where label='first-food_drink'))->'hasPrivateNote','false'::jsonb,'another actor cannot see the owner PrivateNote flag');
select is(public.experience_detail((select experience from m4_cases where label='first-food_drink'))::text like '%Private retained text%',false,'public detail never serializes PrivateNote text');
do $$begin
  perform pg_temp.m4_log('tie-1','outdoors','liked');
  perform pg_temp.m4_log('tie-2','outdoors','liked',pg_temp.m4_answer((select (response->>'ratingID')::uuid from m4_cases where label='tie-1'),'too_tough'));
  perform pg_temp.m4_log('tie-3','outdoors','fine');
end$$;
select is((select jsonb_agg(score order by first_rated_at,id) from public.ratings where owner_id='b4000000-0000-4000-8000-000000000002' and category='outdoors' and sentiment='liked'),'[8.4,8.4]'::jsonb,'a sole tied liked group has8.4 for each member');
select is((select jsonb_agg(rank order by sentiment,first_rated_at,id) from public.ratings where owner_id='b4000000-0000-4000-8000-000000000002' and category='outdoors'),'[1,1,3]'::jsonb,'competition ranks are1,1,3 across tied groups');
reset role;
select is((select count(*)::int from app_private.mutation_receipts where actor_id='a4000000-0000-4000-8000-000000000001' and operation_id=(select (request->>'operationID')::uuid from m4_cases where label='failure')),1,'a failed then successful operation has exactly one durable receipt');
select is((select length(intent_hash) from app_private.mutation_receipts where actor_id='a4000000-0000-4000-8000-000000000001' and operation_id=(select (request->>'operationID')::uuid from m4_cases where label='failure')),64,'server receipt stores SHA256 intent digest');
select is((select count(*)::int from app_private.storage_cleanup where object_path=(select path from m4_assets where label='first') and done_at is null),1,'explicit photo removal queues durable storage cleanup');
select is((select count(*)::int from app_private.storage_cleanup where object_path=(select path from m4_assets where label='second')),0,'ranking removal does not queue cleanup for retained media');
select is((select count(*)::int from app_private.mutation_receipts where actor_id='a4000000-0000-4000-8000-000000000001' and operation_id=(select (request->>'operationID')::uuid from m4_cases where label='atomic')),1,'post-write rollback did not consume the eventual successful UUID');
select is((select count(*)::int from app_private.mutation_receipts where actor_id='a4000000-0000-4000-8000-000000000001' and operation_id=(select (request->>'operationID')::uuid from m4_cases where label='consent-stale')),0,'last-Visit consent rejection does not consume its operation UUID');
set local role anon;
set local request.jwt.claims to '{"role":"anon"}';
select throws_ok($$select public.category_ranking('food_drink')$$,'42501',null,'anonymous callers cannot read rankings');
select throws_ok($$select public.commit_rating('{}')$$,'42501',null,'anonymous callers cannot mutate ratings');
reset role;
select * from finish();
rollback;
